import React, { useState } from 'react';
import { useCreditCollection } from '../../context/CreditCollectionContext';
import { formatCurrency, formatDateDMY } from '../../utils/format';
import { History, ChevronDown, ChevronUp, Receipt, CheckCircle } from 'lucide-react';

export const CollectionHistoryTab: React.FC = () => {
  const { vouchers, requests, filters } = useCreditCollection();
  const [expandedVoucherNo, setExpandedVoucherNo] = useState<string | null>(null);

  // Only show Due Receive vouchers (the ones generated by our feature)
  const collectionVouchers = vouchers.filter(
    (v) =>
      v.voucherType === 'Due Receive (Manual)' ||
      v.voucherType === 'Due Receive (Bulk)'
  );

  const filteredVouchers = collectionVouchers.filter((v) => {
    const q = filters.searchQuery.toLowerCase().trim();
    if (!q) return true;
    return (
      v.voucherNo.toLowerCase().includes(q) ||
      v.narration.toLowerCase().includes(q) ||
      v.actionBy.toLowerCase().includes(q)
    );
  });

  // Look up the matched request for extra info
  const getMatchedRequest = (voucherNo: string) => {
    return requests.find((r) => r.voucherNo === voucherNo);
  };

  const totalCollectedSum = filteredVouchers.reduce((sum, v) => sum + v.totalDebit, 0);

  const toggleExpand = (voucherNo: string) => {
    setExpandedVoucherNo(expandedVoucherNo === voucherNo ? null : voucherNo);
  };

  return (
    <div className="flex-1 flex flex-col bg-white overflow-hidden">
      <div className="flex-1 overflow-x-auto overflow-y-auto max-h-[calc(100vh-14rem)]">
        <table className="w-full text-left border-collapse min-w-[1200px] text-xs">
          <thead className="sticky top-0 bg-[#DCEBFA] text-slate-800 font-semibold z-10 border-b border-[#cbdff4]">
            <tr>
              <th className="py-2.5 px-3 text-center w-12 font-semibold">SL</th>
              <th className="py-2.5 px-3 font-semibold">Voucher No</th>
              <th className="py-2.5 px-3 font-semibold">Date</th>
              <th className="py-2.5 px-3 font-semibold">Voucher Type</th>
              <th className="py-2.5 px-3 font-semibold">Customer</th>
              <th className="py-2.5 px-3 text-right font-semibold">Total Collected</th>
              <th className="py-2.5 px-3 font-semibold">Narration</th>
              <th className="py-2.5 px-3 font-semibold">Posted By</th>
              <th className="py-2.5 px-3 text-center font-semibold">Detail</th>
            </tr>
          </thead>

          <tbody className="divide-y divide-gray-100 text-slate-700">
            {filteredVouchers.length === 0 ? (
              <tr>
                <td colSpan={9} className="py-12 text-center text-slate-400">
                  <div className="flex flex-col items-center justify-center gap-2">
                    <History className="w-8 h-8 text-slate-300" />
                    <p className="font-medium text-slate-500">
                      {filters.searchQuery
                        ? `No collection vouchers matching "${filters.searchQuery}"`
                        : 'No collection vouchers recorded yet. Approve a request to post the first voucher.'}
                    </p>
                  </div>
                </td>
              </tr>
            ) : (
              filteredVouchers.map((voucher, index) => {
                const isExpanded = expandedVoucherNo === voucher.voucherNo;
                const matchedReq = getMatchedRequest(voucher.voucherNo);

                return (
                  <React.Fragment key={voucher.voucherNo}>
                    <tr
                      className={`hover:bg-blue-50/40 transition-colors cursor-pointer ${
                        isExpanded ? 'bg-blue-50/60' : ''
                      }`}
                      onClick={() => toggleExpand(voucher.voucherNo)}
                    >
                      <td className="py-2.5 px-3 text-center text-slate-500 font-medium">
                        {index + 1}
                      </td>

                      {/* Voucher No */}
                      <td className="py-2.5 px-3 font-mono font-bold text-[#2F6FDE]">
                        <div className="flex items-center gap-1.5">
                          <Receipt className="w-3.5 h-3.5 text-blue-500" />
                          <span>{voucher.voucherNo}</span>
                        </div>
                      </td>

                      {/* Date */}
                      <td className="py-2.5 px-3 text-slate-600">
                        {formatDateDMY(voucher.voucherDate)}
                      </td>

                      {/* Voucher Type */}
                      <td className="py-2.5 px-3">
                        <span className={`px-2 py-0.5 rounded text-[10px] font-bold ${
                          voucher.voucherType === 'Due Receive (Bulk)'
                            ? 'bg-purple-100 text-purple-800'
                            : 'bg-blue-100 text-blue-800'
                        }`}>
                          {voucher.voucherType}
                        </span>
                      </td>

                      {/* Customer (from matched request or narration) */}
                      <td className="py-2.5 px-3 font-medium text-slate-800">
                        {matchedReq ? (
                          <div>
                            <div>{matchedReq.customerName}</div>
                            <div className="text-[10px] font-mono text-slate-400">{matchedReq.customerCode}</div>
                          </div>
                        ) : (
                          <span className="text-slate-500 italic text-[11px]">See narration</span>
                        )}
                      </td>

                      {/* Total Collected */}
                      <td className="py-2.5 px-3 text-right font-black text-emerald-700">
                        ৳ {formatCurrency(voucher.totalDebit)}
                      </td>

                      {/* Narration */}
                      <td className="py-2.5 px-3 text-slate-600 max-w-xs truncate">
                        {voucher.narration}
                      </td>

                      {/* Posted By */}
                      <td className="py-2.5 px-3 text-slate-600 font-medium">
                        {voucher.actionBy}
                      </td>

                      {/* Expand Toggle */}
                      <td className="py-2.5 px-3 text-center">
                        <button
                          onClick={(e) => {
                            e.stopPropagation();
                            toggleExpand(voucher.voucherNo);
                          }}
                          className="p-1 rounded hover:bg-slate-200 text-slate-500 transition"
                        >
                          {isExpanded ? (
                            <ChevronUp className="w-4 h-4 text-blue-600" />
                          ) : (
                            <ChevronDown className="w-4 h-4" />
                          )}
                        </button>
                      </td>
                    </tr>

                    {/* Expanded Drawer Row with Journal Lines breakdown */}
                    {isExpanded && (
                      <tr className="bg-slate-50/80">
                        <td colSpan={9} className="p-4 pl-12 border-b border-blue-100">
                          <div className="bg-white rounded border border-blue-100 p-3 shadow-xs">
                            <div className="flex items-center justify-between pb-2 border-b border-gray-100 mb-2">
                              <div className="text-xs font-bold text-slate-800 flex items-center gap-1.5">
                                <CheckCircle className="w-3.5 h-3.5 text-emerald-600" />
                                <span>Journal Lines for Voucher {voucher.voucherNo}</span>
                              </div>
                              {voucher.remarks && (
                                <div className="text-xs text-slate-500 italic">
                                  Remarks: {voucher.remarks}
                                </div>
                              )}
                            </div>

                            <div className="overflow-x-auto">
                              <table className="w-full text-xs border-collapse">
                                <thead className="bg-slate-50">
                                  <tr>
                                    <th className="text-left py-1.5 px-2 font-semibold text-slate-600">Account No</th>
                                    <th className="text-left py-1.5 px-2 font-semibold text-slate-600">Account Name</th>
                                    <th className="text-left py-1.5 px-2 font-semibold text-slate-600">Customer/Supplier</th>
                                    <th className="text-right py-1.5 px-2 font-semibold text-slate-600">Debit</th>
                                    <th className="text-right py-1.5 px-2 font-semibold text-slate-600">Credit</th>
                                  </tr>
                                </thead>
                                <tbody className="divide-y divide-slate-100">
                                  {voucher.lines.map((line) => (
                                    <tr key={line.id} className="hover:bg-blue-50/30">
                                      <td className="py-1.5 px-2 font-mono text-slate-700">{line.chartOfAccountNo}</td>
                                      <td className="py-1.5 px-2 text-slate-700">{line.chartOfAccountName}</td>
                                      <td className="py-1.5 px-2 text-slate-500">{line.customerSupplierEmployee}</td>
                                      <td className="py-1.5 px-2 text-right font-mono text-emerald-700">
                                        {line.debit > 0 ? formatCurrency(line.debit) : '—'}
                                      </td>
                                      <td className="py-1.5 px-2 text-right font-mono text-blue-700">
                                        {line.credit > 0 ? formatCurrency(line.credit) : '—'}
                                      </td>
                                    </tr>
                                  ))}
                                </tbody>
                                <tfoot className="bg-slate-50 font-bold border-t border-slate-200">
                                  <tr>
                                    <td colSpan={3} className="py-1.5 px-2 text-right text-slate-700">Total:</td>
                                    <td className="py-1.5 px-2 text-right font-mono text-emerald-800">
                                      {formatCurrency(voucher.totalDebit)}
                                    </td>
                                    <td className="py-1.5 px-2 text-right font-mono text-blue-800">
                                      {formatCurrency(voucher.totalCredit)}
                                    </td>
                                  </tr>
                                </tfoot>
                              </table>
                            </div>

                            {/* Invoices Affected (from matched request) */}
                            {matchedReq && matchedReq.invoicesAffected.length > 0 && (
                              <div className="mt-3 pt-3 border-t border-blue-100">
                                <div className="text-[11px] font-bold text-slate-700 mb-2 uppercase tracking-wider">
                                  Invoices Settled
                                </div>
                                <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-2">
                                  {matchedReq.invoicesAffected.map((item) => (
                                    <div
                                      key={item.invoiceId}
                                      className="p-2.5 rounded bg-blue-50/40 border border-blue-100 text-xs"
                                    >
                                      <div className="flex justify-between font-mono font-semibold text-slate-800">
                                        <span>#{item.invoiceNo}</span>
                                        <span className="text-emerald-700">
                                          +৳{formatCurrency(item.collectNow)}
                                        </span>
                                      </div>
                                      <div className="flex justify-between text-[11px] text-slate-500 mt-1">
                                        <span>Inv Date: {formatDateDMY(item.invoiceDate)}</span>
                                        <span>
                                          Remaining: ৳{formatCurrency(item.balanceAfter)}
                                        </span>
                                      </div>
                                    </div>
                                  ))}
                                </div>
                              </div>
                            )}
                          </div>
                        </td>
                      </tr>
                    )}
                  </React.Fragment>
                );
              })
            )}
          </tbody>

          {filteredVouchers.length > 0 && (
            <tfoot className="sticky bottom-0 bg-[#F0F5FC] text-slate-800 font-bold border-t-2 border-[#cbdff4] z-10 shadow-inner">
              <tr>
                <td colSpan={5} className="py-2.5 px-3 text-right font-bold uppercase tracking-wider text-slate-700">
                  Total Collected ({filteredVouchers.length} Vouchers):
                </td>
                <td className="py-2.5 px-3 text-right font-black text-emerald-800 text-[13px]">
                  ৳ {formatCurrency(totalCollectedSum)}
                </td>
                <td colSpan={3}></td>
              </tr>
            </tfoot>
          )}
        </table>
      </div>

      <div className="px-6 py-2 bg-slate-50 border-t border-gray-100 flex items-center justify-between text-[11px] text-slate-500">
        <div>Showing {filteredVouchers.length} collection vouchers.</div>
        <div>Click any voucher row to toggle detailed journal line breakdown.</div>
      </div>
    </div>
  );
};
